import{_ as e,o as a,c as o,a2 as s}from"./chunks/framework.hw3Av5Vn.js";const r="/llamatron/assets/synth_asheville.CCc4Q-4d.svg",p=JSON.parse('{"title":"Asheville","description":"","frontmatter":{},"headers":[],"relativePath":"synths/engines/ASHEVILLE.md","filePath":"synths/engines/ASHEVILLE.md"}'),i={name:"synths/engines/ASHEVILLE.md"};function n(d,t,h,l,c,u){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="asheville" tabindex="-1">Asheville <a class="header-anchor" href="#asheville" aria-label="Permalink to &quot;Asheville&quot;">​</a></h1><p>Asheville is the analog mono synth of the 1970s, three oscillators into a ladder filter: the fat, beating lead and bass of the classic three-oscillator monosynth. Its sound is in its three free-running oscillators drifting against each other, a mixer that growls as it is turned up, and the ladder filter that follows. It plays one voice, sliding on glided steps; with Voices raised it plays chords too, each note its own three oscillators, through a filter of its own or one shared, as the polyphonic analogs of the same years did.</p><p><img src="'+r+'" alt="The Oscillators tab of Asheville"></p><h2 id="oscillators-tab" tabindex="-1">Oscillators Tab <a class="header-anchor" href="#oscillators-tab" aria-label="Permalink to &quot;Oscillators Tab&quot;">​</a></h2><p>Each of the three oscillators has its own column:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Choices</th><th>What it does</th></tr></thead><tbody><tr><td>Speed</td><td>Audio, Low, Medium, High</td><td>Audio plays the note at its Range; Low, Medium and High run it at its Rate whatever the note, as an LFO&#39;s Speed does, for the oscillator as a slow modulator through the Mod Matrix</td></tr><tr><td>Rate</td><td>0 to 100%, its hertz shown</td><td>At Low, Medium or High, in the Range&#39;s place, how fast it runs across its Speed&#39;s span, as an LFO&#39;s Rate</td></tr><tr><td>Range</td><td>32&#39;, 16&#39;, 8&#39;, 4&#39;, 2&#39; (Osc 3 also LO)</td><td>The footage: 8&#39; plays the note, each halving of the pipe an octave up; LO, on Osc 3, four octaves under, for an LFO through the Mod Matrix</td></tr><tr><td>Wave</td><td>Triangle, Shark tooth, Saw, Square, Wide pulse, Narrow pulse (Osc 3 Reverse saw in the Shark tooth&#39;s place)</td><td>The panel&#39;s six waves, on the Classic model</td></tr><tr><td>Shape</td><td>0 to 100%</td><td>On the Continuous model, one sweep from triangle at 0 through saw and square to a narrow pulse at 100%, in the Wave&#39;s place</td></tr><tr><td>Tune</td><td>−2400 to +2400 cents</td><td>The oscillator&#39;s tuning against the note, a few cents for the beating that makes it fat, a fifth or an octave for a chord on one key</td></tr><tr><td>Fine</td><td>−10.0 to +10.0 cents</td><td>A tenth of a cent at a time on top of Tune, for slow, lush beating on high notes</td></tr><tr><td>Mix</td><td>0 to 10</td><td>Its level in the mixer</td></tr><tr><td>Sub</td><td>Off, −1 octave, −2 octaves</td><td>A square under the oscillator, one or two octaves down, for weight; off unless chosen</td></tr><tr><td>On</td><td>on or off</td><td>Whether it sounds; switched off, it still runs, so that the Mod Matrix can read it as a source</td></tr></tbody></table><p>And the panel&#39;s own settings:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Choices</th><th>What it does</th></tr></thead><tbody><tr><td>Model</td><td>Classic, Continuous</td><td>The six switched waves, or one Shape to sweep, as the later models have</td></tr><tr><td>Character</td><td>Warm, Cold Start, Worn</td><td>Warm is settled; Cold Start wanders further for its first half minute, as if just switched on; Worn beats more between its oscillators and slips flat high up</td></tr><tr><td>Noise</td><td>0 to 10</td><td>White noise in the mixer, for breath, wind and the hiss under a snare-like hit</td></tr><tr><td>Ring</td><td>0 to 10</td><td>A ring modulator, Osc 1 times Osc 2, mixed in at this level: the clangorous, bell-like sum and difference tones; heard whether or not the two sound themselves</td></tr><tr><td>Snap</td><td>on or off</td><td>Pulls each Tune toward unison, fifths and octaves, so that a chord tuned by ear lands in tune</td></tr><tr><td>Drift</td><td>0 to 10</td><td>How analog the oscillators are, all at once: each sits a few cents off its tuning for good, as its parts put it, a set of its own on every instrument; each wanders slowly on its own over minutes, across notes; and each jitters very slightly from cycle to cycle, so that three oscillators in tune beat and thicken rather than sounding as one</td></tr><tr><td>Feedback</td><td>on or off, with its amount 0 to 10</td><td>Loops the mixer&#39;s output back into it, the classic patch of the output into the external input, for a thicker, overdriven growl</td></tr></tbody></table><p>Each oscillator is also a source in the Mod Matrix, Osc 1, Osc 2 and Osc 3, sounding or switched off: Osc 3 at LO, switched off and routed to the pitch, is the classic vibrato and trill; Osc 2 at audio rate routed to Osc 1&#39;s pitch, or to the cutoff, is analog-style FM. Glide, Glide time and Voices are on the Engine tab every engine shares; the ladder filter is on the Filter tab, its loudness and filter contours on the Envelopes tab.</p><h2 id="how-asheville-is-built" tabindex="-1">How Asheville Is Built <a class="header-anchor" href="#how-asheville-is-built" aria-label="Permalink to &quot;How Asheville Is Built&quot;">​</a></h2><p>Each wave is worked out from its oscillator&#39;s place in its cycle, every sample, its jumps smoothed by a polyBLEP and the triangle&#39;s corners rounded by a polyBLAMP, each over the four samples around it, so that the waves stay bright and clean wherever the pitch goes, under glide, vibrato and audio-rate FM alike. The oscillators keep running between notes, each starting at a place of its own, as free-running oscillators do, so that no two notes start alike. The mixer saturates softly, so three oscillators at full overload it, and Feedback sends its last output back into it.</p><p><a href="./../../SYNTHS">Synths</a> lists every engine. <a href="./../../CREDITS">Credits</a> names the open work it follows.</p>',12)])])}const g=e(i,[["render",n]]);export{p as __pageData,g as default};
